import os
roots = ["/root/.cache", "/home", "/tmp", "/usr/share", "/var", "/data", "/models", "/usr/local/lib/python3.11/site-packages"]
for r in roots:
    if not os.path.exists(r):
        continue
    for dirpath, dirnames, filenames in os.walk(r):
        # prune deep site-packages noise
        if dirpath.count(os.sep) - r.count(os.sep) > 6:
            dirnames[:] = []
            continue
        for f in filenames:
            low = f.lower()
            if low.endswith((".bin",".safetensors",".onnx",".gguf",".msgpack",".pt",".pth")):
                print(os.path.join(dirpath,f))
